    [DataContract] public sealed class JevCalibrationPackage { [DataMember(Order=1)] public string SchemaVersion { get; set; } = "J-B-1"; [DataMember(Order=2)] public string CalibrationPackageId { get; set; } = string.Empty; [DataMember(Order=3)] public string DrawingName { get; set; } = string.Empty; [DataMember(Order=4)] public bool AdvisoryOnly { get; set; } = true; [DataMember(Order=5)] public bool ProductionThresholdSelected { get; set; } [DataMember(Order=6)] public List<JevCalibrationCase> Cases { get; set; } = new List<JevCalibrationCase>(); }
    [DataContract] public sealed class JevCalibrationCase { [DataMember(Order=1)] public string EvidenceId { get; set; } = string.Empty; [DataMember(Order=2)] public string InputProjectionSha256 { get; set; } = string.Empty; [DataMember(Order=3)] public string GeometryKind { get; set; } = string.Empty; [DataMember(Order=4, EmitDefaultValue=false)] public string? LayerName { get; set; } [DataMember(Order=5)] public string CurrentDeterministicState { get; set; } = "Ambiguous"; [DataMember(Order=6)] public List<string> ExistingCandidateKinds { get; set; } = new List<string>(); [DataMember(Order=7)] public List<string> NearbyTextFragments { get; set; } = new List<string>(); [DataMember(Order=8)] public List<string> SpatialContext { get; set; } = new List<string>(); [DataMember(Order=9)] public List<string> MeasurementBasisHints { get; set; } = new List<string>(); [DataMember(Order=10, EmitDefaultValue=false)] public string? SourceRecordType { get; set; } [DataMember(Order=11, EmitDefaultValue=false)] public string? SourceRecordId { get; set; } [DataMember(Order=12, EmitDefaultValue=false)] public string? SubjectKind { get; set; } [DataMember(Order=13, EmitDefaultValue=false)] public string? LabelRawText { get; set; } [DataMember(Order=14, EmitDefaultValue=false)] public string? LabelSourceHandle { get; set; } [DataMember(Order=15, EmitDefaultValue=false)] public string? LabelSourceLayer { get; set; } [DataMember(Order=16, EmitDefaultValue=false)] public double? LabelPositionX { get; set; } [DataMember(Order=17, EmitDefaultValue=false)] public double? LabelPositionY { get; set; } [DataMember(Order=18, EmitDefaultValue=false)] public double? LabelPositionZ { get; set; } [DataMember(Order=19, EmitDefaultValue=false)] public double? AssociationScale { get; set; } [DataMember(Order=20, EmitDefaultValue=false)] public string? Reason { get; set; } [DataMember(Order=21, EmitDefaultValue=false)] public string? SelectedGeometryHandle { get; set; } [DataMember(Order=22, EmitDefaultValue=false)] public double? SelectedDistance { get; set; } [DataMember(Order=23, EmitDefaultValue=false)] public string? Axis { get; set; } [DataMember(Order=24, EmitDefaultValue=false)] public decimal? CoordinateValue { get; set; } [DataMember(Order=25, EmitDefaultValue=false)] public string? SelectedGeometryLayer { get; set; } [DataMember(Order=26, EmitDefaultValue=false)] public string? SelectedGeometryKind { get; set; } [DataMember(Order=27, EmitDefaultValue=false)] public int? SelectedSegmentIndex { get; set; } [DataMember(Order=28, EmitDefaultValue=false)] public string? EngineeringMeasurementBasisKey { get; set; } [DataMember(Order=29)] public List<JevCalibrationCandidate> Candidates { get; set; } = new List<JevCalibrationCandidate>(); }
    [DataContract] public sealed class JevCalibrationCandidate { [DataMember(Order=1)] public string SourceHandle { get; set; } = string.Empty; [DataMember(Order=2)] public string SourceLayer { get; set; } = string.Empty; [DataMember(Order=3)] public string GeometryKind { get; set; } = string.Empty; [DataMember(Order=4, EmitDefaultValue=false)] public bool? Closed { get; set; } [DataMember(Order=5, EmitDefaultValue=false)] public int? VertexCount { get; set; } [DataMember(Order=6)] public double Distance { get; set; } [DataMember(Order=7, EmitDefaultValue=false)] public int? SegmentIndex { get; set; } [DataMember(Order=8, EmitDefaultValue=false)] public double? SegmentStartX { get; set; } [DataMember(Order=9, EmitDefaultValue=false)] public double? SegmentStartY { get; set; } [DataMember(Order=10, EmitDefaultValue=false)] public double? SegmentStartZ { get; set; } [DataMember(Order=11, EmitDefaultValue=false)] public double? SegmentEndX { get; set; } [DataMember(Order=12, EmitDefaultValue=false)] public double? SegmentEndY { get; set; } [DataMember(Order=13, EmitDefaultValue=false)] public double? SegmentEndZ { get; set; } [DataMember(Order=14, EmitDefaultValue=false)] public double? CoordinateDeviation { get; set; } }
