    [DataContract] public sealed class JevEngineerLabel { [DataMember(Order=1)] public string EvidenceId { get; set; } = string.Empty; [DataMember(Order=2)] public string InputProjectionSha256 { get; set; } = string.Empty; [DataMember(Order=3, EmitDefaultValue=false)] public string? EngineerLabel { get; set; } [DataMember(Order=4, EmitDefaultValue=false)] public string? Comment { get; set; } }
    public static class JevCalibrationStates { public const string AwaitingEngineerLabels="AWAITING_ENGINEER_LABELS"; public const string PackageContentMismatch="PACKAGE_CONTENT_MISMATCH"; public const string BenchmarkInputChanged="BENCHMARK_INPUT_CHANGED"; public const string BenchmarkComplete="BENCHMARK_COMPLETE"; }
    public sealed class JevCalibrationPackageStore
    {
        public const string SchemaVersion = "J-D-1";
        public const string LegacySchemaVersion = "J-B-1";
        public static string Root => Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "EngiSentry", "artifacts", "qa", "jev-calibration");
        private readonly string root;
        public JevCalibrationPackageStore() : this(Root) { }
        public JevCalibrationPackageStore(string rootOverride) { root = rootOverride ?? throw new ArgumentNullException(nameof(rootOverride)); }
        public JevCalibrationPackage CreateOrReuse(string drawingName, IReadOnlyList<SemanticAmbiguityCase> cases, out string directory)
        {
            JevCalibrationPackage package = Build(drawingName, cases); directory = Path.Combine(root, package.CalibrationPackageId); Directory.CreateDirectory(directory);
            CreateOrMatch(Path.Combine(directory, "calibration-cases.json"), package, package.CalibrationPackageId);
            JevEngineerLabels template = new JevEngineerLabels { SchemaVersion=package.SchemaVersion, CalibrationPackageId = package.CalibrationPackageId, Labels = package.Cases.Select(c => new JevEngineerLabel { EvidenceId=c.EvidenceId, InputProjectionSha256=c.InputProjectionSha256 }).ToList() };
            CreateOrMatch(Path.Combine(directory, "engineer-labels.template.json"), template, package.CalibrationPackageId);
            string instructions = "Copy engineer-labels.template.json to engineer-labels.json. Edit only EngineerLabel and Comment. Do not modify EvidenceId, InputProjectionSha256, or CalibrationPackageId. Labels may remain null. Only labeled rows participate. EngineerLabel and Comment stay local and are never sent to TypeSafe. This does not activate automatic semantic resolution.";
            CreateOrMatchText(Path.Combine(directory, "LABELING_INSTRUCTIONS.md"), instructions);
            return package;
        }
        public JevCalibrationPackage CreateOrReuse(string drawingName, PlotPlanModel plan, IReadOnlyList<SemanticAmbiguityCase> cases, out string directory)
        {
            JevCalibrationPackage package = BuildEnriched(drawingName, plan, cases); directory = Path.Combine(root, package.CalibrationPackageId); Directory.CreateDirectory(directory);
            CreateOrMatch(Path.Combine(directory, "calibration-cases.json"), package, package.CalibrationPackageId);
            JevEngineerLabels template = new JevEngineerLabels { SchemaVersion=package.SchemaVersion, CalibrationPackageId=package.CalibrationPackageId, Labels=package.Cases.Select(c=>new JevEngineerLabel { EvidenceId=c.EvidenceId, InputProjectionSha256=c.InputProjectionSha256 }).ToList() };
            CreateOrMatch(Path.Combine(directory, "engineer-labels.template.json"), template, package.CalibrationPackageId);
            CreateOrMatchText(Path.Combine(directory, "LABELING_INSTRUCTIONS.md"), "Use calibration-cases.json for local drawing evidence. Copy engineer-labels.template.json to engineer-labels.json. Edit only EngineerLabel and Comment. Do not modify EvidenceId, InputProjectionSha256, or CalibrationPackageId. Detailed local drawing evidence is not sent to TypeSafe. EngineerLabel remains human engineering input and does not activate automatic semantic resolution.");
            return package;
        }
        public static JevCalibrationPackage Build(string drawingName, IReadOnlyList<SemanticAmbiguityCase> cases)
        {
            List<JevCalibrationCase> items=(cases??new List<SemanticAmbiguityCase>()).Select(c=>new JevCalibrationCase { EvidenceId=c.EvidenceId,InputProjectionSha256=JevSemanticAssistPayloadBuilder.ComputeSha256(c),GeometryKind=c.GeometryKind,LayerName=c.LayerName,CurrentDeterministicState=c.CurrentDeterministicState,ExistingCandidateKinds=c.ExistingCandidateKinds,NearbyTextFragments=c.NearbyTextFragments,SpatialContext=c.SpatialContext,MeasurementBasisHints=c.MeasurementBasisHints }).OrderBy(c=>c.EvidenceId,StringComparer.Ordinal).ToList();
            return Package(LegacySchemaVersion,drawingName,items);
        }
        public static JevCalibrationPackage BuildEnriched(string drawingName, PlotPlanModel plan, IReadOnlyList<SemanticAmbiguityCase> cases) => Package(SchemaVersion,drawingName,JevCalibrationCaseBuilder.Build(plan,cases));
        public static List<JevEngineerLabel> LoadValidLabels(string directory,JevCalibrationPackage package)
        {
            string path=Path.Combine(directory,"engineer-labels.json"); if(!File.Exists(path)) return new List<JevEngineerLabel>();
            JevEngineerLabels labels=Read<JevEngineerLabels>(path); if(!Supported(package.SchemaVersion)||labels.SchemaVersion!=package.SchemaVersion||labels.CalibrationPackageId!=package.CalibrationPackageId) throw new InvalidOperationException("PACKAGE_CONTENT_MISMATCH");
            if(labels.Labels.GroupBy(x=>x.EvidenceId,StringComparer.Ordinal).Any(g=>g.Count()!=1)) throw new InvalidOperationException("PACKAGE_CONTENT_MISMATCH");
            Dictionary<string,JevCalibrationCase> expected=package.Cases.ToDictionary(x=>x.EvidenceId,StringComparer.Ordinal);
            foreach(JevEngineerLabel label in labels.Labels){if(!expected.TryGetValue(label.EvidenceId,out JevCalibrationCase? item)||item.InputProjectionSha256!=label.InputProjectionSha256||(!string.IsNullOrWhiteSpace(label.EngineerLabel)&&!JevSemanticLabels.All.Contains(label.EngineerLabel))||(label.Comment?.Length??0)>500)throw new InvalidOperationException("PACKAGE_CONTENT_MISMATCH");}
            return labels.Labels.Where(x=>!string.IsNullOrWhiteSpace(x.EngineerLabel)).OrderBy(x=>x.EvidenceId,StringComparer.Ordinal).ToList();
        }
        private static void CreateOrMatch<T>(string path,T value,string identity){if(File.Exists(path)){T existing=Read<T>(path);if(!string.Equals(Serialize(existing),Serialize(value),StringComparison.Ordinal))throw new InvalidOperationException("PACKAGE_CONTENT_MISMATCH");return;}using(FileStream s=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None))new DataContractJsonSerializer(typeof(T)).WriteObject(s,value);}
        private static void CreateOrMatchText(string path,string value){if(File.Exists(path)){if(File.ReadAllText(path)!=value)throw new InvalidOperationException("PACKAGE_CONTENT_MISMATCH");return;}using(FileStream s=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None))using(StreamWriter w=new StreamWriter(s,new UTF8Encoding(false)))w.Write(value);}
        private static T Read<T>(string path){using(FileStream s=File.OpenRead(path))return (T)new DataContractJsonSerializer(typeof(T)).ReadObject(s)!;}
        private static string Serialize<T>(T value){using(MemoryStream s=new MemoryStream()){new DataContractJsonSerializer(typeof(T)).WriteObject(s,value);return Convert.ToBase64String(s.ToArray());}}
        private static JevCalibrationPackage Package(string schemaVersion,string drawingName,List<JevCalibrationCase> items){string canonical=schemaVersion+"\n"+(drawingName??string.Empty)+"\n"+string.Join("\n",items.OrderBy(c=>c.EvidenceId,StringComparer.Ordinal).Select(c=>c.EvidenceId+"|"+c.InputProjectionSha256));return new JevCalibrationPackage { SchemaVersion=schemaVersion,CalibrationPackageId=Hash(canonical),DrawingName=drawingName??string.Empty,Cases=items.OrderBy(c=>c.EvidenceId,StringComparer.Ordinal).ToList() };}
        private static bool Supported(string schemaVersion)=>schemaVersion==LegacySchemaVersion||schemaVersion==SchemaVersion;
        private static string Hash(string value){using(SHA256 h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(value))).Replace("-",string.Empty);}
    }

    public static class JevCalibrationCaseBuilder
    {
        public static List<JevCalibrationCase> Build(PlotPlanModel plan, IReadOnlyList<SemanticAmbiguityCase> cases)
        {
            if(plan==null) throw new ArgumentNullException(nameof(plan)); var sources=new List<Source>();
            sources.AddRange((plan.Geometry.Associations??new List<GeometryAssociation>()).Where(a=>Eligible(a.Status,a.SubjectKind)).Select(a=>new Source(Hash("geometry|"+a.AssociationId),a)));
            sources.AddRange((plan.Geometry.SpatialConstraints??new List<SpatialCoordinateConstraint>()).Where(c=>Eligible(c.Status,c.SubjectKind)).Select(c=>new Source(Hash("spatial|"+c.ConstraintId),c)));
            return (cases??new List<SemanticAmbiguityCase>()).Select(c=>Map(c,sources)).OrderBy(c=>c.EvidenceId,StringComparer.Ordinal).ToList();
        }
        private static bool Eligible(string status,string subject)=>status=="Ambiguous"&&(subject=="Road"||subject=="Boundary");
        private static JevCalibrationCase Map(SemanticAmbiguityCase item,List<Source> sources)
        {
            List<Source> matches=sources.Where(s=>s.EvidenceId==item.EvidenceId).ToList(); if(matches.Count!=1) throw new InvalidOperationException("CALIBRATION_MAPPING_ERROR"); Source source=matches[0];
            JevCalibrationCase value=Base(item); if(source.Association!=null) Fill(value,source.Association); else Fill(value,source.Constraint!); return value;
        }
        private static JevCalibrationCase Base(SemanticAmbiguityCase c)=>new JevCalibrationCase { EvidenceId=c.EvidenceId,InputProjectionSha256=JevSemanticAssistPayloadBuilder.ComputeSha256(c),GeometryKind=c.GeometryKind,LayerName=c.LayerName,CurrentDeterministicState=c.CurrentDeterministicState,ExistingCandidateKinds=(c.ExistingCandidateKinds??new List<string>()).ToList(),NearbyTextFragments=(c.NearbyTextFragments??new List<string>()).ToList(),SpatialContext=(c.SpatialContext??new List<string>()).ToList(),MeasurementBasisHints=(c.MeasurementBasisHints??new List<string>()).ToList() };
        private static void Fill(JevCalibrationCase value,GeometryAssociation a){value.SourceRecordType="GeometryAssociation";value.SourceRecordId=a.AssociationId;value.SubjectKind=a.SubjectKind;value.LabelRawText=a.LabelRawText;value.LabelSourceHandle=a.LabelSourceHandle;value.LabelSourceLayer=a.LabelSourceLayer;value.LabelPositionX=a.LabelPositionX;value.LabelPositionY=a.LabelPositionY;value.LabelPositionZ=a.LabelPositionZ;value.AssociationScale=a.AssociationScale;value.Reason=a.Reason;value.SelectedGeometryHandle=a.SelectedGeometryHandle;value.SelectedDistance=a.SelectedDistance;value.Candidates=(a.Candidates??new List<GeometryCandidate>()).Select(c=>new JevCalibrationCandidate { SourceHandle=c.SourceHandle,SourceLayer=c.SourceLayer,GeometryKind=c.GeometryKind,Closed=c.Closed,VertexCount=c.VertexCount,Distance=c.Distance }).ToList();}
        private static void Fill(JevCalibrationCase value,SpatialCoordinateConstraint c){value.SourceRecordType="SpatialCoordinateConstraint";value.SourceRecordId=c.ConstraintId;value.SubjectKind=c.SubjectKind;value.LabelRawText=c.LabelRawText;value.LabelSourceHandle=c.LabelSourceHandle;value.LabelSourceLayer=c.LabelSourceLayer;value.LabelPositionX=c.LabelPositionX;value.LabelPositionY=c.LabelPositionY;value.LabelPositionZ=c.LabelPositionZ;value.AssociationScale=c.AssociationScale;value.Reason=c.Reason;value.SelectedGeometryHandle=c.SelectedGeometryHandle;value.SelectedDistance=c.SelectedDistance;value.Axis=c.Axis;value.CoordinateValue=c.CoordinateValue;value.SelectedGeometryLayer=c.SelectedGeometryLayer;value.SelectedGeometryKind=c.SelectedGeometryKind;value.SelectedSegmentIndex=c.SelectedSegmentIndex;value.EngineeringMeasurementBasisKey=c.EngineeringMeasurementBasisKey;value.Candidates=(c.Candidates??new List<SpatialGeometryCandidate>()).Select(x=>new JevCalibrationCandidate { SourceHandle=x.SourceHandle,SourceLayer=x.SourceLayer,GeometryKind=x.GeometryKind,SegmentIndex=x.SegmentIndex,SegmentStartX=x.SegmentStartX,SegmentStartY=x.SegmentStartY,SegmentStartZ=x.SegmentStartZ,SegmentEndX=x.SegmentEndX,SegmentEndY=x.SegmentEndY,SegmentEndZ=x.SegmentEndZ,Distance=x.Distance,CoordinateDeviation=x.CoordinateDeviation }).ToList();}
        private static string Hash(string value){using(SHA256 h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(value))).Replace("-",string.Empty);}
        private sealed class Source { internal Source(string evidenceId,GeometryAssociation association){EvidenceId=evidenceId;Association=association;} internal Source(string evidenceId,SpatialCoordinateConstraint constraint){EvidenceId=evidenceId;Constraint=constraint;} internal string EvidenceId { get; } internal GeometryAssociation? Association { get; } internal SpatialCoordinateConstraint? Constraint { get; } }
    }
}
